            self.chat_display.insert(END, f"\nAI: {response}\n", "ai")
            self.chat_display.tag_configure("ai", foreground="#4CAF50")

            if resolved_model and provider:
                self.status_var.set(f"Reponse de {provider}:{resolved_model}")
            else:
                self.status_var.set("Ready to chat...")

        except Exception as e:
            self.chat_display.insert(END, f"\nError: {str(e)}\n", "error")
            self.chat_display.tag_configure("error", foreground="#f44336")
            self.status_var.set("Ready to chat...")

        self.chat_display.see(END)
        self.root.update()


def main():
    root = Tk()
    ChatGUI(root)
    root.mainloop()


if __name__ == "__main__":
    main()
