class ConversationManager:
    """Manages conversations with multiple LLM providers"""

    def __init__(self, db_path: str = "conversations.db"):
        self.db_path = db_path
        self.current_conversation: Optional[Conversation] = None
        self.conversations: Dict[str, Conversation] = {}
        self.providers: Dict[str, LLMProviderBase] = {}
        self.lock = threading.RLock()

        self._init_db()
        self._init_providers()

    def _init_providers(self):
        """Initialize all available LLM providers"""
        self.providers = {
            "openai": OpenAIProvider(),
            "mistral": MistralProvider(),
            "ollama": OllamaProvider(),
            "azure": AzureOpenAIProvider(),
            "fallback": FallbackProvider(),
        }

        available = [name for name, prov in self.providers.items() if prov.available]
        logger.info(f"Available LLM providers: {available}")

    def _init_db(self):
        """Initialize SQLite database for conversation storage"""
        with sqlite3.connect(self.db_path) as conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS conversations (
                    id TEXT PRIMARY KEY,
                    title TEXT,
                    created_at TEXT,
                    updated_at TEXT,
                    provider TEXT,
                    model TEXT,
                    temperature REAL,
                    max_tokens INTEGER,
                    system_prompt TEXT,
                    metadata TEXT
                )
            """)

            conn.execute("""
                CREATE TABLE IF NOT EXISTS messages (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    conversation_id TEXT,
                    role TEXT,
                    content TEXT,
                    timestamp TEXT,
                    metadata TEXT,
                    FOREIGN KEY(conversation_id) REFERENCES conversations(id)
                )
            """)
            conn.commit()

    def create_conversation(
        self,
        title: str,
        provider: str = "openai",
        model: str = "gpt-3.5-turbo",
        system_prompt: Optional[str] = None,
        **kwargs
    ) -> Conversation:
        """Create new conversation"""
        conv_id = hashlib.md5(
            f"{title}{datetime.now().isoformat()}".encode()
        ).hexdigest()

        conv = Conversation(
            id=conv_id,
            title=title,
            provider=provider,
            model=model,
            system_prompt=system_prompt,
            **kwargs
        )

        with self.lock:
            self.conversations[conv_id] = conv
            self.current_conversation = conv
            self._save_conversation(conv)

        return conv

    def load_conversation(self, conv_id: str) -> Optional[Conversation]:
        """Load conversation from database"""
        try:
            with sqlite3.connect(self.db_path) as conn:
                cursor = conn.execute(
                    "SELECT * FROM conversations WHERE id = ?", (conv_id,)
                )
                row = cursor.fetchone()

                if not row:
                    return None

                conv = Conversation(
                    id=row[0],
                    title=row[1],
                    created_at=datetime.fromisoformat(row[2]),
                    updated_at=datetime.fromisoformat(row[3]),
                    provider=row[4],
                    model=row[5],
                    temperature=row[6],
                    max_tokens=row[7],
                    system_prompt=row[8],
                    metadata=json.loads(row[9]) if row[9] else {}
                )

                # Load messages
                messages = conn.execute(
                    "SELECT role, content, timestamp, metadata FROM messages WHERE conversation_id = ? ORDER BY id",
                    (conv_id,)
                ).fetchall()

                for role, content, timestamp, meta in messages:
                    conv.messages.append(
                        Message(
                            role=role,
                            content=content,
                            timestamp=datetime.fromisoformat(timestamp),
                            metadata=json.loads(meta) if meta else {}
                        )
                    )

                with self.lock:
                    self.conversations[conv_id] = conv

                return conv
        except Exception as e:
            logger.error(f"Error loading conversation: {str(e)}")
            return None

    def _save_conversation(self, conv: Conversation):
        """Save conversation to database"""
        try:
            with sqlite3.connect(self.db_path) as conn:
                conn.execute(
                    """INSERT OR REPLACE INTO conversations
                    (id, title, created_at, updated_at, provider, model, temperature, max_tokens, system_prompt, metadata)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        conv.id, conv.title,
                        conv.created_at.isoformat(), conv.updated_at.isoformat(),
                        conv.provider, conv.model, conv.temperature, conv.max_tokens,
                        conv.system_prompt,
                        json.dumps(conv.metadata)
                    )
                )
                conn.commit()
        except Exception as e:
            logger.error(f"Error saving conversation: {str(e)}")

